  const refresh=async()=>{if(workspaceMode!=="account"){setLoading(false);return}try{const response=await fetch("/api/missions",{credentials:"same-origin",cache:"no-store"});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Saved mission progress is unavailable.");setServerMissions(body.missions||[]);setJourney(body.journey||null);setNotice("")}catch(error){setNotice(error.message||"Saved mission progress is unavailable.")}finally{setLoading(false)}};
