 const loadCommunityList=async()=>{if(workspaceMode!=='account')return;try{const response=await fetch('/api/community',{credentials:'same-origin',cache:'no-store'});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Community spaces are unavailable.');setCommunities(body.communities||[]);if(!(body.communities||[]).some(item=>item.id===communityId&&item.joined))setCommunityId((body.communities||[]).find(item=>item.joined)?.id||'community-general')}catch(error){setNotice(error.message||'Community spaces are unavailable.')}}
 useEffect(()=>{loadCommunityList()},[workspaceMode]);
 useEffect(()=>{let alive=true;const load=async()=>{if(workspaceMode!=='account'||!['feed','chat'].includes(tab))return;const loadKey=tab+':'+communityId;const firstLoad=loadedCommunityKey.current!==loadKey;if(firstLoad){loadedCommunityKey.current=loadKey;setCommunityLoading(true)}try{const endpoint=tab==='feed'?'posts':'messages';const response=await fetch('/api/community/'+endpoint+'?communityId='+encodeURIComponent(communityId),{credentials:'same-origin',cache:'no-store'});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Join this community to continue.');if(!alive)return;if(tab==='feed')setFeed((body.posts||[]).map(post=>({id:post.id,text:post.body,displayName:post.display_name||post.displayName||'Member',createdAt:post.created_at||post.createdAt,commentCount:Number(post.commentCount||0),reactionCount:Number(post.reactionCount||0),liked:Boolean(post.liked)})));else setChat((body.messages||[]).map(message=>({id:message.id,text:message.body,displayName:message.display_name||message.displayName||'Member',createdAt:message.created_at||message.createdAt})));setNotice('')}catch(error){if(alive){if(tab==='feed')setFeed([]);else setChat([]);setNotice(error.message||'Community content is unavailable.')}}finally{if(alive&&firstLoad)setCommunityLoading(false)}};load();const timer=setInterval(load,tab==='chat'?7000:20000);return()=>{alive=false;clearInterval(timer)}},[workspaceMode,tab,communityId]);
 const [tradeType,setTradeType]=useState('manual');
 const [selectedTrade,setSelectedTrade]=useState('');
 const [notice,setNotice]=useState('');
 const [clanName,setClanName]=useState('');
 const [joinCode,setJoinCode]=useState('');
 const eligible=history.filter(t=>Number(t.realizedPnl??t.realized_pnl_tc??0)>0&&Boolean(t.aiManaged??t.ai_managed)===(tradeType==='ai'));
 const bestTrade=eligible.slice().sort((a,b)=>Number(b.realizedPnl??b.realized_pnl_tc??0)-Number(a.realizedPnl??a.realized_pnl_tc??0))[0];
 const chosenTrade=eligible.find(t=>String(t.id)===String(selectedTrade))||bestTrade;
 const tradePnl=t=>Number(t?.realizedPnl??t?.realized_pnl_tc??0);
 const tradeMarket=t=>String(t?.market||t?.symbol||'Crypto market');
 const tradeDirection=t=>String(t?.direction||((t?.side||'long')==='short'?'Short':'Long'));
 const tradeReturn=t=>{const base=Number(t?.amount??t?.reserved_tc??0);return base>0?tradePnl(t)/base*100:0};
 const safeXml=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 const caption=chosenTrade?'I just completed a '+tradeDirection(chosenTrade)+' simulated practice trade on '+tradeMarket(chosenTrade)+', recording +'+money(tradePnl(chosenTrade))+' TC ('+tradeReturn(chosenTrade).toFixed(2)+'% simulated return). Practise your strategy with Pexoriy: '+window.location.origin:'';
 const downloadCard=()=>{
  if(!chosenTrade){setNotice('Close a profitable simulated practice trade before creating a Trade Success Card.');return}
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><rect width="1200" height="630" rx="34" fill="#10120f"/><circle cx="1050" cy="90" r="210" fill="#b7f34a" opacity=".08"/><rect x="54" y="54" width="1092" height="522" rx="26" fill="#171b14" stroke="#3a4530" stroke-width="2"/><text x="94" y="120" fill="#b7f34a" font-family="Arial,sans-serif" font-size="25" font-weight="700" letter-spacing="5">PEXORIY</text><text x="94" y="182" fill="#f3f5ee" font-family="Arial,sans-serif" font-size="37" font-weight="700">TRADE SUCCESS</text><text x="94" y="230" fill="#a9b09f" font-family="Arial,sans-serif" font-size="22">Verified simulated practice result</text><text x="94" y="330" fill="#b7f34a" font-family="Arial,sans-serif" font-size="68" font-weight="700">+'+safeXml(money(tradePnl(chosenTrade)))+' TC</text><text x="94" y="380" fill="#f3f5ee" font-family="Arial,sans-serif" font-size="25">'+safeXml(tradeMarket(chosenTrade))+' · '+safeXml(tradeDirection(chosenTrade))+'</text><text x="94" y="426" fill="#a9b09f" font-family="Arial,sans-serif" font-size="22">'+safeXml(tradeReturn(chosenTrade).toFixed(2))+'% simulated return</text><path d="M94 465H1106" stroke="#343d2d"/><text x="94" y="510" fill="#d0d5c8" font-family="Arial,sans-serif" font-size="18">Simulated trading only. No real exchange trade or profit.</text><text x="94" y="545" fill="#b7f34a" font-family="Arial,sans-serif" font-size="18">Practise. Compete. Grow. · '+safeXml(window.location.host)+'</text></svg>';
  const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pexoriy-trade-success.svg';document.body.appendChild(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1500);setNotice('Your standardized Trade Success Card was downloaded. Simulated results are clearly labelled.');
 };
 const shareCard=async()=>{
  if(!chosenTrade){setNotice('No eligible profitable closed trade is available to share yet.');return}
  try{if(navigator.share){await navigator.share({title:'My Pexoriy Trade Success',text:caption,url:window.location.origin});setNotice('Share sheet opened. Your simulated-trading disclosure is included.')}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(caption);setNotice('Share caption copied. Download the card image to share it with your caption.')}else{setNotice('Sharing is not supported in this browser. Download the card and copy this caption manually: '+caption)}}catch(error){if(error?.name!=='AbortError')setNotice('Sharing was not completed. You can still download the card image.')}
 };
 const checkCommunityText=text=>{const result=moderateCommunityText(text);if(!result.ok){setNotice(result.message);return false}return true};
 const joinCommunity=async()=>{if(workspaceMode!=='account'){setNotice('Sign in to join and participate in persistent community spaces.');return}try{const response=await fetch('/api/community/join',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({communityId})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Could not join this community.');await loadCommunityList();setNotice('You joined this community. Its posts and group chat are now available.')}catch(error){setNotice(error.message||'Could not join this community.')}}
 const postToFeed=async()=>{const text=draft.trim();if(!text||!checkCommunityText(text))return;if(workspaceMode!=='account'){setNotice('Sign in to publish a post that your community can see.');return}if(!selectedCommunity?.joined){setNotice('Join this community before posting.');return}try{const response=await fetch('/api/community/posts',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({communityId,body:text})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Your post could not be published.');setFeed(prev=>[{id:body.post.id,text:body.post.body,displayName:body.post.displayName||'You',createdAt:body.post.createdAt,commentCount:0,reactionCount:0,liked:false},...prev]);setDraft('');setNotice('Post published to '+(selectedCommunity?.name||'your community')+'.')}catch(error){setNotice(error.message||'Your post could not be published.')}}
 const sendChat=async()=>{const text=chatDraft.trim();if(!text||!checkCommunityText(text))return;if(workspaceMode!=='account'){setNotice('Sign in to send a message to your community group chat.');return}if(!selectedCommunity?.joined){setNotice('Join this community before sending a message.');return}try{const response=await fetch('/api/community/messages',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({communityId,body:text})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Your message could not be sent.');setChat(prev=>[...prev,{id:body.message.id,text:body.message.body,displayName:body.message.displayName||'You',createdAt:body.message.createdAt}]);setChatDraft('');setNotice('Message sent to '+(selectedCommunity?.name||'your community')+'.')}catch(error){setNotice(error.message||'Your message could not be sent.')}}
 const reactToPost=async post=>{if(workspaceMode!=='account'){setNotice('Sign in to react to community posts.');return}try{const response=await fetch('/api/community/react',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({postId:post.id,reaction:'like'})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Your reaction could not be saved.');setFeed(prev=>prev.map(item=>item.id===post.id?{...item,liked:body.reacted,reactionCount:Math.max(0,item.reactionCount+(body.reacted?1:-1))}:item))}catch(error){setNotice(error.message||'Your reaction could not be saved.')}}
 const toggleComments=async post=>{const next=!openComments[post.id];setOpenComments(prev=>({...prev,[post.id]:next}));if(!next||commentsByPost[post.id])return;try{const response=await fetch('/api/community/comments?postId='+encodeURIComponent(post.id),{credentials:'same-origin',cache:'no-store'});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Comments could not be loaded.');setCommentsByPost(prev=>({...prev,[post.id]:body.comments||[]}))}catch(error){setNotice(error.message||'Comments could not be loaded.')}}
 const submitComment=async post=>{const text=String(commentDrafts[post.id]||'').trim();if(!text||!checkCommunityText(text))return;if(workspaceMode!=='account'){setNotice('Sign in to comment on community posts.');return}try{const response=await fetch('/api/community/comments',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({postId:post.id,body:text})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Comment could not be saved.');setCommentsByPost(prev=>({...prev,[post.id]:[...(prev[post.id]||[]),{...body.comment,display_name:body.comment.displayName}]}));setCommentDrafts(prev=>({...prev,[post.id]:''}));setFeed(prev=>prev.map(item=>item.id===post.id?{...item,commentCount:item.commentCount+1}:item));setOpenComments(prev=>({...prev,[post.id]:true}));setNotice('Comment added.')}catch(error){setNotice(error.message||'Comment could not be saved.')}}

