  {tab==='feed'&&<div className="community-panel community-comms-panel">{communitySwitcher}<div className="community-panel-heading"><div><span className="eyebrow">COMMUNITY FEED</span><h2>Share something useful.</h2></div><MessageCircle size={20}/></div><p className="community-panel-description">Share useful practice learnings with members of your own Pexoriy Circle only—not the whole platform. External links, phone numbers, spam, abuse, and deceptive financial claims are blocked by the composer guardrails.</p><form className="community-composer" onSubmit={e=>{e.preventDefault();postToFeed()}}><textarea value={draft} maxLength={500} onChange={e=>setDraft(e.target.value)} placeholder="What did you learn from your latest practice session?" aria-label="Write a community post"/><div><span>{draft.length}/500 · {selectedCommunity?.joined?'Visible to this community':'Join to publish'}</span><button className="btn btn-primary" type="submit" disabled={!draft.trim()||!selectedCommunity?.joined||communityLoading}>Post update <Send size={14}/></button></div></form>{communityLoading?<div className="community-empty">Loading community posts…</div>:feed.length===0?<div className="community-empty"><Users size={23}/><strong>{selectedCommunity?.joined?'Your feed starts here.':'Join this community to read its posts.'}</strong><span>{selectedCommunity?.joined?'Start a useful discussion. Posts are saved and visible to members of this community.':'Choose Join community above to unlock this space.'}</span></div>:<div className="community-post-list">{feed.map(post=><article className="community-post" key={post.id}><div className="community-avatar">{String(post.displayName||'PX').slice(0,2).toUpperCase()}</div><div><div className="community-post-meta"><strong>{post.displayName||'Member'}</strong><span>{post.createdAt?new Date(post.createdAt).toLocaleString():''} · Community post</span></div><p>{post.text}</p><div className="community-post-actions"><button className="btn btn-outline community-reaction-button" type="button" onClick={()=>reactToPost(post)}>{post.liked?'♥ Liked':'♡ Like'} · {post.reactionCount||0}</button><button className="btn btn-outline community-reaction-button" type="button" onClick={()=>toggleComments(post)}>{openComments[post.id]?'Hide comments':'Comments'} · {post.commentCount||0}</button></div>{openComments[post.id]&&<div className="community-comment-thread">{(commentsByPost[post.id]||[]).map(comment=><div className="community-comment" key={comment.id}><strong>{comment.display_name||comment.displayName||'Member'}</strong><p>{comment.body}</p></div>)}<form onSubmit={e=>{e.preventDefault();submitComment(post)}}><input maxLength={1000} value={commentDrafts[post.id]||''} onChange={e=>setCommentDrafts(prev=>({...prev,[post.id]:e.target.value}))} placeholder="Add a helpful comment…" aria-label="Add a comment"/><button className="btn btn-primary" type="submit" disabled={!String(commentDrafts[post.id]||'').trim()}>Comment</button></form></div>}</div></article>)}</div>}</div>}
