function Referrals({navigate,workspaceMode,setTC,history=[],positions=[]}) {
  const [data,setData]=useState(null),[loading,setLoading]=useState(true),[notice,setNotice]=useState(""),[communitySection,setCommunitySection]=useState('overview');
  useEffect(()=>{let alive=true;if(workspaceMode!=="account"){setData(null);setNotice("");setLoading(false);return()=>{alive=false}}setLoading(true);(async()=>{try{await fetch("/api/referrals/activate",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:"{}"}).catch(()=>{});const response=await fetch("/api/referrals",{credentials:"same-origin",cache:"no-store"});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Referral data is unavailable.");if(alive){setData(body);setNotice("")}}catch(error){if(alive)setNotice(error.message||"Referral data is unavailable.")}finally{if(alive)setLoading(false)}})();return()=>{alive=false}},[workspaceMode]);
  const inviteUrl=data?.code?window.location.origin+"/?ref="+encodeURIComponent(data.code):"";
  const copyInviteLink=async()=>{if(!inviteUrl){setNotice(workspaceMode==="account"?"Your personal invite link is still being prepared.":"Sign in to create a tracked personal invite link.");return}try{await navigator.clipboard.writeText(inviteUrl);setNotice("Your personal invite link has been copied.")}catch{setNotice("Copy this invite link: "+inviteUrl)}};
  const sharePexoriy=async()=>{if(!inviteUrl){setNotice(workspaceMode==="account"?"Your personal invite link is still being prepared.":"Sign in to create a tracked personal invite link.");return}const message="Join me on Pexoriy — practise crypto trading, learn with AI tools, and take on community challenges.";try{if(navigator.share)await navigator.share({title:"Join me on Pexoriy",text:message,url:inviteUrl});else await copyInviteLink()}catch{await copyInviteLink()}};
  const claimQuest=async quest=>{if(workspaceMode!=="account"){setNotice("Sign in to claim server-verified team quest rewards.");return}try{const response=await fetch("/api/referrals/quests/claim",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify({questId:quest.id})});const body=await response.json().catch(()=>({}));if(!response.ok){setNotice(body.error||"The team quest could not be claimed.");return}if(response.status===202){setNotice(body.message||"Quest reward is being reconciled safely.");return}if(body.rewardTC&&!body.duplicate&&setTC)setTC(value=>value+Number(body.rewardTC));setNotice(body.duplicate?"This team quest reward was already recorded.":"Team quest completed: +"+body.rewardTC+" TC recorded.");const refresh=await fetch("/api/referrals",{credentials:"same-origin",cache:"no-store"});const refreshed=await refresh.json().catch(()=>({}));if(refresh.ok)setData(refreshed)}catch{setNotice("The team quest could not be claimed. Please try again.")}};
  const invited=Number(data?.invited||0),activated=Number(data?.activated||0);
  return <><Heading eyebrow="INVITE & GROW" title={<>Invite friends. <em>Grow together.</em></>} desc="Build your Pexoriy Circle, help members grow, and track meaningful invites and clear rewards."/>
  <nav className="invite-grow-nav" aria-label="Invite and community sections">{[['overview','Overview'],['clans','Clans'],['tasks','Tasks & quests'],['feed','Community feed'],['chat','Group chats'],['campaigns','Growth campaigns'],['report','Weekly report'],['success','Success card']].map(([id,label])=><button key={id} type="button" className={communitySection===id?'active':''} aria-current={communitySection===id?'page':undefined} onClick={()=>setCommunitySection(id)}>{label}</button>)}</nav>
  {communitySection!=='overview'&&<CommunityHub history={history} positions={positions} workspaceMode={workspaceMode} navigate={navigate} initialTab={communitySection} externalNav onOpenReferrals={()=>setCommunitySection('overview')}/>}
  {communitySection==='overview'&&<>
  <section className="referral-hero referral-hub-hero"><div className="referral-hub-copy"><span className="referral-kicker"><Users size={14}/> YOUR PEXORIY CIRCLE</span><p>One tracked link. Clear personal rewards. Shared progress.</p><div className="referral-flow"><div><span className="referral-step-icon"><Gift size={17}/></span><strong>Invite</strong><small>Share your link</small></div><ArrowRight size={16}/><div><span className="referral-step-icon"><Users size={17}/></span><strong>Activate</strong><small>Verify + practice</small></div><ArrowRight size={16}/><div><span className="referral-step-icon"><Trophy size={17}/></span><strong>Grow together</strong><small>Unlock milestones</small></div></div>
  <div className="referral-community-proof"><span className="referral-community-count">{loading?"—":Number(data?.community?.verifiedActivations||0)}</span><span>verified activations across the Pexoriy community</span></div><div className="referral-share-link"><div><small>YOUR PERSONAL INVITE LINK</small><strong>{loading?"Loading your link…":inviteUrl||"Sign in to generate your link"}</strong></div><button onClick={copyInviteLink} disabled={loading||workspaceMode!=="account"||!inviteUrl}>Copy link <Copy size={14}/></button></div>
  <div className="referral-actions"><Btn kind="lime" onClick={sharePexoriy} disabled={loading||workspaceMode!=="account"}>Invite friends <ArrowRight size={16}/></Btn><span>Verified activation: 250 TC to the inviter and 100 TC to the new member. Verified TC history may contribute to a future PXY allocation; no fixed conversion or guaranteed amount is promised.</span></div>
  {workspaceMode!=="account"&&<p className="referral-inline-notice">Create an account or sign in to get a tracked personal invite link.</p>}{notice&&<p className="referral-inline-notice" role="status">{notice}</p>}</div><div className="referral-visual"><div className="referral-orbit orbit-a"/><div className="referral-orbit orbit-b"/><div className="referral-avatar avatar-main">P</div><div className="referral-avatar avatar-one"><Users size={18}/></div><div className="referral-avatar avatar-two"><Flame size={17}/></div><div className="referral-avatar avatar-three"><Trophy size={17}/></div><div className="referral-bubble"><Sparkles size={14}/> Build your circle</div></div></section>

  <section className="invite-journey-panel" aria-labelledby="invite-journey-title">
    <div className="invite-journey-heading"><div><span className="eyebrow">YOUR GROWTH PATH</span><h2 id="invite-journey-title">Turn invitations into shared progress.</h2><p>Follow each step from sharing your link to verified community activity.</p></div><span className="invite-journey-count">{workspaceMode!=="account"||loading?"—":activated+" verified"}</span></div>
    <div className="invite-journey-steps">
      <div className="invite-journey-step complete"><span className="invite-journey-number"><Share2 size={16}/></span><div><strong>Share your link</strong><small>Invite people you know to join Pexoriy.</small></div><span className="invite-step-state">Start here</span></div>
      <div className={"invite-journey-step "+(activated>=1?"complete":"")}><span className="invite-journey-number"><ShieldCheck size={16}/></span><div><strong>First verified activation</strong><small>A referred member verifies their account and records a simulated trade.</small></div><span className="invite-step-state">{workspaceMode!=="account"||loading?"Sign in":activated>=1?"Reached":"1 activation"}</span></div>
      <div className={"invite-journey-step "+(activated>=3?"complete":"")}><span className="invite-journey-number"><Users size={16}/></span><div><strong>Build your squad</strong><small>Reach 3 verified activations to hit this community milestone.</small></div><span className="invite-step-state">{workspaceMode!=="account"||loading?"—":Math.min(activated,3)+"/3"}</span></div>
      <div className={"invite-journey-step "+(activated>=5?"complete":"")}><span className="invite-journey-number"><Trophy size={16}/></span><div><strong>Grow the arena</strong><small>Reach 5 verified activations and explore cooperative quests.</small></div><span className="invite-step-state">{workspaceMode!=="account"||loading?"—":Math.min(activated,5)+"/5"}</span></div>
    </div>
    <div className="invite-journey-footer"><ShieldCheck size={15}/><span>Progress updates from your account. Rewards are only shown as earned after server verification; milestones do not guarantee extra rewards unless a published quest says so.</span></div>
  </section>
  <section className="invite-next-actions" aria-label="Continue growing your Circle">
    <button type="button" onClick={()=>setCommunitySection("clans")}><span className="invite-next-icon"><Users size={18}/></span><span><strong>Create or join a Circle</strong><small>Find your team and see membership options.</small></span><ArrowRight size={17}/></button>
    <button type="button" onClick={()=>setCommunitySection("tasks")}><span className="invite-next-icon"><Target size={18}/></span><span><strong>Continue team quests</strong><small>Review objectives, progress, and eligible claims.</small></span><ArrowRight size={17}/></button>
    <button type="button" onClick={()=>setCommunitySection("report")}><span className="invite-next-icon"><CalendarClock size={18}/></span><span><strong>Review your weekly report</strong><small>See the community progress summary.</small></span><ArrowRight size={17}/></button>
    <button type="button" onClick={()=>setCommunitySection("success")}><span className="invite-next-icon"><Share2 size={18}/></span><span><strong>Share a success card</strong><small>Make eligible progress easy to share.</small></span><ArrowRight size={17}/></button>
  </section>
  <section className="referral-stats-grid"><div className="referral-stat"><span className="referral-stat-icon"><Users size={18}/></span><div><small>Friends invited</small><strong>{workspaceMode!=="account"||loading?"—":invited}</strong><span>Tracked registrations</span></div></div><div className="referral-stat"><span className="referral-stat-icon purple"><Activity size={18}/></span><div><small>Verified activations</small><strong>{workspaceMode!=="account"||loading?"—":activated}</strong><span>Email verified + first simulated trade</span></div></div><div className="referral-stat"><span className="referral-stat-icon orange"><Trophy size={18}/></span><div><small>Next milestone</small><strong>{workspaceMode!=="account"?"Sign in to track":activated<1?"First connection":activated<3?"Build your squad":activated<5?"Grow the arena":"Milestones reached"}</strong><span>{workspaceMode!=="account"?"Verified referral progress is account-backed":activated<1?"1 active referral":activated<3?(3-activated)+" more to reach 3":activated<5?(5-activated)+" more to reach 5":"Keep helping new traders learn"}</span></div></div></section>
  <section className="panel referral-rewards-panel"><div className="referral-rewards-icon"><Sparkles size={21}/></div><div><span className="eyebrow">VERIFIED PARTICIPATION</span><h3>Meaningful invites. Clear rewards.</h3><p>Activation requires a verified account and at least one recorded simulated trade. TC rewards are ledger-posted once per referral. Self-referrals are rejected; PXY is not part of this program.</p></div><Btn kind="outline" onClick={()=>navigate("Learning Center")}>Learn before you invite <ArrowRight size={15}/></Btn></section></>}{communitySection!=='overview'&&<div className="community-hub-footer-note"><ShieldCheck size={15}/><span>Community publishing, moderation, membership scoping, sanctions, and admin review must be enforced by the server before these tools are used for real member communication.</span></div>}</>;
}
