class PageErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { failed: false };
  }
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error, info) {
    console.error("Pexoriy page render failed:", this.props.screenName, error, info?.componentStack || "");
  }
  render() {
    if (this.state.failed) return <section className="panel page-render-error" role="alert">
      <ShieldCheck size={22}/>
      <h2>This screen could not load</h2>
      <p>{this.props.screenName || "This page"} hit an unexpected display error. Your account data has not been changed by this screen error.</p>
      <button className="btn btn-outline" onClick={() => this.setState({ failed: false })}>Try loading again</button>
    </section>;
    return this.props.children;
  }
}

